const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='sunny-english-v1',today=()=>new Date().toLocaleDateString('en-CA'),intervals=[1,2,3,7,16];
let state={name:'Sunny',goal:40,done:{},words:{},answers:{},notes:{},activity:{}};try{const stored=JSON.parse(localStorage.getItem(key));if(stored&&typeof stored==='object')state={...state,...stored};}catch{}
let lesson=1,section='vocab',wordIndex=0,revealed=false,promptIndex=0,filter='全部',wordFilter='到期复习',listenStage=0,recording=null,stream=null,audioUrl=null,recordTimer=null;
const timings=()=>state.goal===20?[8,5,5,2]:state.goal===60?[25,15,15,5]:[15,10,10,5];
const labels=['词汇与短语','三遍听力','情景口语','复习与总结'],sections=['vocab','listening','speaking','review'];
const current=()=>lessons[lesson-1],wid=(l,i)=>`${l}-${i}`,isDone=(l,s)=>!!state.done[`${l}-${s}`];
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('浏览器未能保存记录，请导出备份。');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
function speak(text,slow=false){if(!('speechSynthesis'in window)){toast('此浏览器不支持朗读，请使用支持语音的浏览器。');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=slow?.72:.9;const v=speechSynthesis.getVoices().find(v=>/^en-US/.test(v.lang))||speechSynthesis.getVoices().find(v=>/^en/.test(v.lang));if(v)u.voice=v;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('语音播放不可用，请检查设备语音设置。');};speechSynthesis.speak(u);}
function cleanup(){if('speechSynthesis'in window)speechSynthesis.cancel();if(recording?.state==='recording')recording.stop();stream?.getTracks().forEach(t=>t.stop());clearTimeout(recordTimer);if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null;}}
function done(){state.done[`${lesson}-${section}`]=true;const d=today();state.activity[d]||=[];const id=`${lesson}-${section}`;if(!state.activity[d].includes(id))state.activity[d].push(id);save();toast('已记录这一步的学习进度');render();}
function learned(l,i,know){const id=wid(l,i),old=state.words[id]||{level:0};const level=know?Math.min(old.level+1,5):0;state.words[id]={level,due:Date.now()+(know?intervals[Math.min(level-1,4)]:0)*86400000,seen:true};save();}
function progress(){return sections.filter(s=>isDone(lesson,s)).length;}
function pageHeading(title,sub){return `<div class="page-top"><h1>${title}</h1><p>${sub}</p></div>`;}
function render(){const page=(location.hash||'#today').slice(1);document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page||(page==='lesson'&&a.dataset.page==='courses')));const names={today:'今日学习',courses:'我的课程',words:'单词与复习',speaking:'口语练习室',plan:'学习路线',lesson:'课程练习'};$('#breadcrumb').innerHTML=`我的学习空间 <span>/ ${names[page]||'今日学习'}</span>`;$('#date').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});$('.header-right .pill').textContent=`每天 ${state.goal} 分钟`;$('.profile>span:nth-child(2)').innerHTML=`${esc(state.name)}<small>我的学习偏好</small>`;$('#view').innerHTML=({today:dashboard,courses:courses,lesson:lessonView,words:wordsView,speaking:speakingRoom,plan:planView}[page]||dashboard)();bind();}
function dashboard(){const mins=timings(),a=state.activity[today()]||[],todayMins=a.reduce((n,id)=>n+mins[sections.indexOf(id.split('-')[1])],0),days=Object.keys(state.activity).filter(d=>state.activity[d].length).length,seen=Object.keys(state.words).length;let next=lessons.find(l=>!sections.every(s=>isDone(l.id,s)))||lessons[6];let week='';const date=new Date(),dow=(date.getDay()+6)%7;for(let i=0;i<7;i++){const d=new Date(date);d.setDate(date.getDate()-dow+i);const completed=state.activity[d.toLocaleDateString('en-CA')]?.length;week+=`<div class="day">${'一二三四五六日'[i]}<i class="${completed?'filled':i===dow?'current':''}">${completed?'✓':i===dow?'·':''}</i></div>`;}
return `<div class="intro"><div><h1>你好，${esc(state.name)} <span style="font-size:24px">☀</span></h1><p>每天 ${state.goal} 分钟，让英语走进你的工作与生活。</p></div><span class="streak">✧ 已有 ${days} 天，为自己积累一点进步</span></div><div class="dashboard"><div><section class="hero"><div class="hero-content"><span class="eyebrow">第一周 · 从熟悉的场景开始</span><h2>${next.title}</h2><p>从认识一个词，到说出一句话。<br>今天，再向真实交流靠近一点。</p><button class="light" data-start="${next.id}">${sections.some(s=>isDone(next.id,s))?'继续学习':'开始今天的学习'} <span>↗</span></button><div class="hero-meta">Lesson ${String(next.id).padStart(2,'0')} &nbsp; · &nbsp; Basic &nbsp; · &nbsp; 词汇优先</div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="speech">Hello.</div><div class="speech two">你好！</div><span class="spark">✧</span></div></section><div class="section-heading"><h2>今天的学习节奏</h2><span>四小步，慢慢积累</span></div><section class="tasks">${labels.map((t,i)=>`<div class="task"><span class="task-icon">${['Aa','♫','◌','↻'][i]}</span><div><h3>${t}</h3><p>${['10 个新词，放进真实句子里','先盲听，再理解，最后跟读','从一个问题开始，练习说出口','记住今天不会说的表达'][i]}</p></div><span class="duration">${mins[i]} 分钟</span><button data-task="${sections[i]}" data-l="${next.id}" class="${isDone(next.id,sections[i])?'done':''}">${isDone(next.id,sections[i])?'✓ 完成':'开始'}</button></div>`).join('')}</section><div class="bottom-banner"><span style="font-size:25px;color:#819372">♧</span><div><h3>词汇先行，也给开口留一点时间</h3><p>HR 系统与审批流程 · 工作、生活各占一半</p></div><a href="#plan">查看学习路线 ↗</a></div></div><div class="right-column"><section class="right-panel"><h3>我的今日进度</h3><div class="progress-circle" style="--progress:${Math.min(100,todayMins/state.goal*100)}%"><div><strong>${todayMins}<span style="font-size:12px;color:#97a18f"> / ${state.goal}</span></strong><small>已完成计划分钟</small></div></div><p class="progress-text">完成学习步骤后记录，按计划时长统计</p><div class="week">${week}</div><div class="split-stat"><div><strong>${seen}</strong><small>已接触词汇</small></div><div><strong>${lessons.filter(l=>sections.every(s=>isDone(l.id,s))).length}</strong><small>已完成课程</small></div></div></section><section class="right-panel daily-phrase"><span class="eyebrow" style="color:#8b9a7c">今天，试着说一句</span><div class="quote">“Let me check<br>and get back to you.”</div><p>我确认一下，再回复你。</p><div class="phrase-bottom"><span>工作沟通 · 留一点思考的时间</span><button class="audio-btn" data-say="Let me check and get back to you." aria-label="播放每日一句">♫</button></div></section></div></div>`;}
function courses(){return pageHeading('我的课程','第一周 · 工作 3 课，日常与出国 4 课。按自己的节奏学习，随时回来复习。')+`<div class="tabs">${['全部','工作','日常','出国'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f}</button>`).join('')}</div><div class="course-grid">${lessons.filter(l=>filter==='全部'||l.category===filter).map(l=>`<article class="course"><span class="eyebrow">Lesson ${String(l.id).padStart(2,'0')} · ${l.category}</span><h2>${l.title}</h2><p>${l.topic}</p><span class="badge">${l.words.length} 个词汇与短语</span><div class="course-foot"><span>${sections.filter(s=>isDone(l.id,s)).length} / 4 步完成</span><button class="secondary" data-start="${l.id}">进入课程 ↗</button></div></article>`).join('')}</div>`;}
function lessonView(){const l=current();return pageHeading(`Lesson ${String(l.id).padStart(2,'0')} · ${l.title}`,`${l.topic} · ${state.goal} 分钟 · Basic`)+`<div class="tabs">${labels.map((t,i)=>`<button data-section="${sections[i]}" class="${section===sections[i]?'active':''}">${isDone(lesson,sections[i])?'✓ ':''}${t} · ${timings()[i]}′</button>`).join('')}</div><div class="learning-layout"><div>${({vocab:vocabView,listening:listeningView,speaking:speakingView,review:reviewView}[section])()}</div><aside><div class="panel"><h3>这一课，慢慢来</h3><ul class="tip-list"><li>学习 ${l.words.length} 个词汇或短语</li><li>听懂一段场景对话</li><li>回答 5 个简单问题</li><li>留下值得复习的一句话</li></ul><p class="review-note">${progress()} / 4 步完成。完成记录可在当前浏览器继续查看。</p><a href="#courses" class="text-link">← 返回课程目录</a></div></aside></div>`;}
function vocabView(){const l=current(),w=l.words[wordIndex];return `<section class="panel"><div class="word-progress"><span>词汇卡片 ${wordIndex+1} / ${l.words.length}</span><span>先回想，再看答案</span></div><div class="word-card"><h2>${esc(w[0])}</h2><div class="phonetic">${esc(w[1])}</div><button class="audio-btn" style="margin-top:16px" data-say="${esc(w[0])}" aria-label="播放单词">♫</button>${revealed?`<p>${esc(w[2])}</p><p class="example">${esc(w[3])}</p><p class="translation">${esc(w[4])}</p><button class="secondary" data-say="${esc(w[3])}">♫ 听例句</button>`:`<p class="muted" style="margin-top:32px">你记得它的含义吗？试着说一个句子。</p><button class="secondary" id="reveal">查看释义与例句</button>`}</div><div class="actions"><button class="secondary" id="prev-word" ${wordIndex===0?'disabled':''}>← 上一个</button><button class="secondary" data-rate="0">还不熟悉</button><button class="primary" data-rate="1">记住了，继续 →</button></div><p class="review-note">记住的词会在第 2、4、7、14 天进入复习；不熟悉的词会留在待复习列表。</p><div class="actions"><button class="secondary" id="complete">标记词汇步骤完成 ✓</button></div></section>`;}
function listeningView(){const l=current();return `<section class="panel"><span class="eyebrow">${l.en}</span><h2>${l.topic}</h2><p class="muted">朗读使用设备英语语音，由浏览器合成。先听大意，再抓住关键词。</p><div class="tabs">${['1 · 盲听','2 · 英文字幕','3 · 跟读与中文'].map((x,i)=>`<button data-stage="${i}" class="${listenStage===i?'active':''}">${x}</button>`).join('')}</div><div class="actions" style="justify-content:flex-start"><button class="primary" id="play-dialogue">♫ 播放对话</button><button class="secondary" id="slow-dialogue">慢速播放</button><button class="secondary" id="stop-speech">停止</button></div>${listenStage===0?'<div class="empty">先不看字幕，听听他们在聊什么。<br><small>准备好后，切换到「英文字幕」。</small></div>':`<div class="transcript">${l.lines.map((line,i)=>`<div class="dialogue-line"><strong>${line[0]}</strong><div><p>${esc(line[1])}</p>${listenStage===2?`<small>${line[2]}</small><button class="text-link" style="border:0;background:none;padding:8px 0" data-say="${esc(line[1])}">♫ 单句跟读</button>`:''}</div></div>`).join('')}</div>`}<form id="quiz" class="quiz"><h3>听懂了吗？</h3>${l.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${q[0]}</legend>${q[1].map((a,j)=>`<label><input required type="radio" name="q${i}" value="${j}"> ${a}</label>`).join('')}</fieldset>`).join('')}<button class="primary">检查答案</button><div id="quiz-result" role="status"></div></form><div class="actions"><button id="complete" class="secondary">完成听力步骤 ✓</button></div></section>`;}
function speakingView(){const p=current().prompts[promptIndex],a=state.answers[`${lesson}-${promptIndex}`]||'';return `<section class="panel"><div class="word-progress"><span>情景对练 · 第 ${promptIndex+1} / 5 轮</span><span>一次练习一个问题</span></div><div class="prompt">${esc(p[0])}<div class="translation" style="margin-top:10px">${p[1]}</div></div><div class="actions" style="justify-content:flex-start"><button class="secondary" data-say="${esc(p[0])}">♫ 听问题</button><button class="secondary" id="record">● 录音练习</button><button class="secondary" id="stop-record" disabled>停止录音</button></div><p id="record-status" class="muted">录音仅保留在本页，刷新后清除；不上传。</p><audio id="record-audio" controls class="hidden"></audio><label for="answer" class="muted">也可以写下你的回答（自动保存）</label><textarea id="answer" placeholder="Try a simple sentence…">${esc(a)}</textarea><details style="margin-top:18px"><summary>说完后，看看参考表达</summary><div class="feedback">${esc(p[2])}<br><button class="secondary" data-say="${esc(p[2])}">♫ 跟读参考句</button></div><p class="muted">参考答案可按自己的真实情况修改。此版本不提供 AI 评分或发音诊断。</p></details><div class="actions"><button class="secondary" id="prev-prompt" ${promptIndex===0?'disabled':''}>← 上一题</button><button class="primary" id="next-prompt">${promptIndex===4?'完成口语步骤 ✓':'保存并练下一题 →'}</button></div></section>`;}
function reviewView(){return `<section class="panel"><h2>把今天的表达带走</h2><p class="muted">朗读下面的句子，再试着替换其中的信息。</p>${current().phrases.map(s=>`<div class="word-row"><div>${esc(s)}</div><button class="audio-btn" data-say="${esc(s)}" aria-label="播放句子">♫</button></div>`).join('')}<label for="notes"><p>今天哪个词或哪句话还不熟悉？</p></label><textarea id="notes" placeholder="例如：approver 和 applicant 容易混淆…">${esc(state.notes[lesson]||'')}</textarea><div class="actions"><button class="primary" id="complete">保存并完成复习 ✓</button><a class="secondary" href="#words">去复习词汇 →</a></div></section>`;}
function wordsView(){let all=lessons.flatMap(l=>l.words.map((w,i)=>({w,l:l.id,i,entry:state.words[wid(l.id,i)]}))),due=all.filter(x=>x.entry&&x.entry.due<=Date.now());let list=wordFilter==='到期复习'?due:wordFilter==='工作词汇'?all.filter(x=>lessons[x.l-1].category==='工作'):all;return pageHeading('单词与复习',`认识、理解、用出来。${Object.keys(state.words).length} 个已接触词汇 · ${due.length} 个待复习。`)+`<div class="tabs">${['到期复习','工作词汇','全部词汇'].map(f=>`<button data-word-filter="${f}" class="${wordFilter===f?'active':''}">${f}</button>`).join('')}</div><div class="panel"><label class="muted" for="word-search">搜索英文或中文</label><input id="word-search" placeholder="例如 approval / 审批" style="width:100%;margin:12px 0"><div class="word-list">${list.length?list.map(({w,l,i,entry})=>`<div class="word-row" data-search="${esc(w.join(' ').toLowerCase())}"><div><strong>${esc(w[0])}</strong> <span class="muted">${esc(w[2])}</span><small>${esc(w[3])}</small>${entry?`<small>${entry.level?`下次复习：${new Date(entry.due).toLocaleDateString('zh-CN')}`:'待巩固'}</small>`:''}</div><button class="audio-btn" data-say="${esc(w[0])}" aria-label="播放 ${esc(w[0])}">♫</button><button class="secondary" data-word="${l},${i}">练习</button></div>`).join(''):'<div class="empty">今天没有到期词汇。<br>可以从「工作词汇」开始，积累第一组实用表达。</div>'}</div><p id="no-match" class="empty hidden">没有找到匹配的词汇。</p></div>`;}
function speakingRoom(){return pageHeading('口语练习室','从 HR 审批沟通到日常交流。每个场景包含 5 个问题，可以听、录、写，再对照表达。')+`<div class="course-grid">${lessons.map(l=>`<div class="course"><span class="badge">${l.category}</span><h2 style="margin-top:15px">${l.topic}</h2><p>${l.prompts[0][0]}</p><div class="course-foot"><span>5 轮 · 录音回听</span><button class="primary" data-practice="${l.id}">开始练习 ↗</button></div></div>`).join('')}</div>`;}
function planView(){return pageHeading('学习路线','工作与日常各占一半，兼顾出国。先积累高频词汇，再逐渐增加听说难度。')+`<div class="panel"><h2>前期：词汇优先，每天 ${state.goal} 分钟</h2><div class="time-grid">${labels.map((l,i)=>`<div><strong>${timings()[i]}′</strong><small>${l}</small></div>`).join('')}</div><p class="muted">平日学新内容；周六复习词汇与模拟审批沟通；周日轻量听力与自由表达。忙碌日可在学习偏好中切换为 20 分钟。</p></div><div class="panel"><h2>从熟悉的内部系统，走向真实交流</h2><div class="timeline">${[['第 1 个月 · 积累能用的词','每天约 10 个词或短语，重点掌握员工、部门、请假单、报销、审批人、权限与流程状态。能用简单句介绍工作和日常需求。'],['第 2～3 个月 · 用句子讲清楚','练习入职、转正、调岗、离职流程，说明复现步骤、预期与实际结果；练习餐厅、交通、酒店情景。'],['第 4～6 个月 · 独立参与沟通','逐渐增加自然语速、跨部门需求确认、审批分支与权限讨论，练习表达意见和追问。'],['第 7～12 个月 · 扩展表达','练习长对话、缺陷评审与海外生活，按听说表现调整难度。']].map(([h,p])=>`<article><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><p class="review-note">当前已提供第一周 7 课、70 个词汇卡片。后续阶段是学习规划，课程尚待补充；阶段目标随实际进展调整。</p></div><div class="panel"><h2>复习节奏</h2><p>当天学习 → 第 2 天 → 第 4 天 → 第 7 天 → 第 14 天</p><p class="muted">每次选择「记住了」后推进下一轮复习；选择「还不熟悉」会回到待复习列表。每天先复习，再学新词。</p></div>`;}
function start(l,s='vocab'){cleanup();lesson=Number(l);section=s;wordIndex=0;revealed=false;promptIndex=0;listenStage=0;if(location.hash==='#lesson')render();else location.hash='lesson';window.scrollTo(0,0);}
function bind(){document.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>start(b.dataset.l,b.dataset.task));document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>start(b.dataset.practice,'speaking'));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-word-filter]').forEach(b=>b.onclick=()=>{wordFilter=b.dataset.wordFilter;render();});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{cleanup();section=b.dataset.section;render();});document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{listenStage=+b.dataset.stage;render();});document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{const [l,i]=b.dataset.word.split(',');start(l);wordIndex=+i;render();});
$('#reveal')?.addEventListener('click',()=>{revealed=true;render();});$('#prev-word')?.addEventListener('click',()=>{wordIndex--;revealed=false;render();});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{if(!revealed){revealed=true;render();toast('先看看释义和例句，再判断熟悉程度。');return;}learned(lesson,wordIndex,b.dataset.rate==='1');if(wordIndex<current().words.length-1){wordIndex++;revealed=false;render();}else{toast('本组词汇已记录，可标记步骤完成或再次复习。');render();}});$('#complete')?.addEventListener('click',done);
$('#play-dialogue')?.addEventListener('click',()=>speak(current().lines.map(l=>l[1]).join('\n')));$('#slow-dialogue')?.addEventListener('click',()=>speak(current().lines.map(l=>l[1]).join('\n'),true));$('#stop-speech')?.addEventListener('click',()=>speechSynthesis.cancel());$('#quiz')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);let correct=0;const results=current().quiz.map((q,i)=>{const ok=Number(f.get(`q${i}`))===q[2];if(ok)correct++;return `${ok?'✓':'○'} ${q[0]} — ${q[1][q[2]]}`;});$('#quiz-result').innerHTML=`<div class="feedback">答对 ${correct} / ${current().quiz.length} 题<br>${results.map(esc).join('<br>')}</div>`;});
$('#answer')?.addEventListener('input',e=>{state.answers[`${lesson}-${promptIndex}`]=e.target.value;save();});$('#notes')?.addEventListener('input',e=>{state.notes[lesson]=e.target.value;save();});$('#next-prompt')?.addEventListener('click',()=>{cleanup();if(promptIndex<4){promptIndex++;render();}else done();});$('#prev-prompt')?.addEventListener('click',()=>{cleanup();promptIndex--;render();});$('#record')?.addEventListener('click',record);$('#stop-record')?.addEventListener('click',()=>{recording?.stop();clearTimeout(recordTimer);});
$('#word-search')?.addEventListener('input',e=>{let count=0;document.querySelectorAll('[data-search]').forEach(row=>{const match=row.dataset.search.includes(e.target.value.toLowerCase().trim());row.classList.toggle('hidden',!match);if(match)count++;});$('#no-match').classList.toggle('hidden',count>0||!e.target.value);});}
async function record(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器无法录音，请使用 HTTPS 或本地浏览器。');return;}const button=$('#record');button.disabled=true;const activeLesson=lesson,activePrompt=promptIndex;try{if('speechSynthesis'in window)speechSynthesis.cancel();stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!document.contains(button)||activeLesson!==lesson||activePrompt!==promptIndex){stream.getTracks().forEach(t=>t.stop());return;}const chunks=[];recording=new MediaRecorder(stream);recording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recording.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(!document.contains(button))return;if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(new Blob(chunks,{type:recording.mimeType}));$('#record-audio').src=audioUrl;$('#record-audio').classList.remove('hidden');$('#record-status').textContent='录音完成。听一遍，再对照参考表达。';button.disabled=false;$('#stop-record').disabled=true;};recording.start();$('#stop-record').disabled=false;$('#record-status').textContent='正在录音… 说完后点击停止，最长 2 分钟。';recordTimer=setTimeout(()=>{if(recording.state==='recording')recording.stop();},120000);}catch{button.disabled=false;toast('未能使用麦克风。可检查权限，或先写下回答练习。');}}
$('#settings').onclick=()=>{$('#name-input').value=state.name;$('#goal-input').value=state.goal;$('#preferences').showModal();};$('#save-settings').onclick=e=>{if(!$('#name-input').value.trim()){e.preventDefault();return;}state.name=$('#name-input').value.trim();state.goal=+$('#goal-input').value;save();render();};$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=`sunny-english-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());const mapKeys=['done','words','answers','notes','activity'];if(typeof d.name!=='string'||d.name.length>30||![20,40,60].includes(d.goal)||mapKeys.some(k=>!d[k]||typeof d[k]!=='object'||Array.isArray(d[k])))throw Error();if(Object.entries(d.words).some(([k,w])=>!/^\d+-\d+$/.test(k)||!w||!Number.isInteger(w.level)||w.level<0||w.level>5||!Number.isFinite(w.due)))throw Error();if(Object.values(d.activity).some(v=>!Array.isArray(v)||v.some(id=>!/^([1-7])-(vocab|listening|speaking|review)$/.test(id))))throw Error();state={name:d.name,goal:d.goal,...Object.fromEntries(mapKeys.map(k=>[k,d[k]]))};save();render();toast('学习记录已导入');}catch{toast('文件格式不正确，请选择本网站导出的记录。');}e.target.value='';};
$('#header-settings').onclick=()=>$('#settings').click();
window.addEventListener('hashchange',()=>{cleanup();render();window.scrollTo(0,0);});window.addEventListener('beforeunload',cleanup);render();
